function startTubeMission(autoStart=false){if(!chapterLoadingBypass)return loadChapterScreen('TUBE · EDGWARE TO EMBANKMENT',()=>startTubeMission(autoStart));if(!canOpenTube())return;if(isKevinStoryRoute()){resetKevinPostTubeProgress();delete gameProgress.kevinTubeClashChoice;delete gameProgress.kevinTubeClashWinner;gameProgress.tubeCompleted=false;saveProgress();}menu();setMode('tube');world.visible=upperWorld.visible=exhibit.visible=false;for(const a of [subject,peter,alissa,gareth,stephen,chrisMenu,mariahMenu,garethJonesMenu,emmaMenu,kevinMenu,kevinRevealed,elizabethMenu])a.visible=false;const t=tubeMission={root:new THREE.Group(),elapsed:0,station:-1,paused:true,ended:false,seated:false,sleepTime:0,hp:100,ammo:12,reload:0,cooldown:0,enemies:[],spawn:0,doors:[],stationLabels:[],notice:'Alissa is aboard. Stay on the train to Embankment.',noticeTime:15,kills:0,allyCooldown:0,last:performance.now()};scene.add(t.root);buildTubeCarriage(t);player.set(0,1.65,2);yaw=0;pitch=0;scene.fog.density=.002;scene.background.setHex(0x4c5965);ambient.intensity=1.1;flash.visible=false;camera.position.copy(player);camera.rotation.set(0,0,0);$('tubeHUD').hidden=false;tubeOverlay('EDGWARE → EMBANKMENT','A real-time, 32-minute southbound train journey via Charing Cross. Alissa is seated nearby. Travel to Embankment; stay alert after Camden Town. Press E beside a seat to sit, then F to SLEEP UNTIL CAMDEN. Journey time pauses when the game is paused.','start');updateTubeHUD();if(autoStart===true){t.paused=false;t.transitionUntil=performance.now()+1000;$('tubeOverlay').hidden=true;keys.clear();}}
function clearTubeMission(){stopTubeBetrayalVoice();stopTubeDreamVoice();stopCamdenMaskedVoice();window.speechSynthesis?.cancel();const t=tubeMission;if(t){if(t.camdenRoot){scene.remove(t.camdenRoot);t.camdenRoot.traverse(o=>{o.geometry?.dispose();});}if(t.cinemaRoot){scene.remove(t.cinemaRoot);t.cinemaRoot.traverse(o=>{o.geometry?.dispose();});}scene.remove(t.root);camera.remove(t.gun);t.root.traverse(o=>{o.geometry?.dispose();if(o.material){for(const m of Array.isArray(o.material)?o.material:[o.material]){m.map?.dispose();m.dispose();}}});}tubeMission=null;$('tubeHUD').classList.remove('camden-route');for(const id of ['tubeHUD','tubeOverlay','tubeSleepFade','tubeSeatPrompt','tubeDream','tubeCamdenChoice','tubeKevinRouteEnd','tubeCamdenPrompt','tubeCamdenTalk','tubeEndingUI'])if($(id))$(id).hidden=true;}
function tubeOverlay(title,text,kind){$('tubeContinueTyrant').hidden=kind!=='won'||!canOpenTyrantFour();$('tubeOverlay').hidden=false;$('tubeOverlayTitle').textContent=title;$('tubeOverlayText').textContent=text;$('tubeResume').hidden=!['start','pause'].includes(kind);$('tubeRetry').hidden=kind!=='lost';}
function pauseTube(){const t=tubeMission;if(!t||t.ended||t.dream||t.camdenChoice)return;t.paused=true;keys.clear();tubeOverlay('JOURNEY PAUSED','The train and combat are paused. Resume when you are ready.','pause');document.exitPointerLock?.();}
function resumeTube(){if(!tubeMission||tubeMission.ended)return;tubeMission.paused=false;tubeMission.last=performance.now();$('tubeOverlay').hidden=true;requestLock();}
function finishTube(won){const t=tubeMission;if(!t||t.ended)return;if(won){startTubeBetrayal();return;}t.ended=true;t.paused=true;t.gun.visible=false;keys.clear();document.exitPointerLock?.();if(won){gameProgress.tubeCompleted=true;saveProgress();refreshProgressUI();tubeOverlay('TO BE CONTINUED','EMBANKMENT. You and Alissa have survived the journey. Chapter 3 complete. Your progress has been saved.','won');}else tubeOverlay('JOURNEY ENDED','The masked assailants overwhelmed you before Embankment.','lost');}
function tubeNotice(s){tubeMission.notice=s;tubeMission.noticeTime=7;}
function spawnTubeNinja(){const t=tubeMission;if(t.enemies.length>=4)return;const actor=makeCampNinja();actor.scale.setScalar(.83);actor.position.set((Math.random()-.5)*.8,0,player.z>0?-16:16);t.root.add(actor);t.enemies.push({actor,hp:100,attack:1});tubeNotice('Masked swordsmen have entered the carriage. Protect yourself!');}
function hurtTubeEnemy(e,damage){const t=tubeMission;e.hp-=damage;if(e.hp<=0){t.root.remove(e.actor);e.actor.traverse(o=>{o.geometry?.dispose();if(o.material)o.material.dispose();});t.enemies.splice(t.enemies.indexOf(e),1);t.kills++;t.hp=Math.min(100,t.hp+8);tubeNotice('Assailant stopped · +8 health');}}
function shootTube(){const t=tubeMission;if(mode!=='tube'||!t||t.paused||t.ended||t.seated||t.dream||t.camdenChoice||t.camdenExplore||t.sleepTime>0||t.reload>0||t.cooldown>0)return;if(!t.ammo){reloadTube();return;}t.ammo--;t.cooldown=.23;playGunshot(.55);t.muzzle.visible=true;camera.updateMatrixWorld(true);t.root.updateMatrixWorld(true);const ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2(0,0),camera);const hits=ray.intersectObjects(t.enemies.map(e=>e.actor),true);if(hits.length){let o=hits[0].object;while(o&&!t.enemies.some(e=>e.actor===o))o=o.parent;const e=t.enemies.find(e=>e.actor===o);if(e){hurtTubeEnemy(e,40);$('tubeReticle').style.color='#ed5266';}}}
function reloadTube(){const t=tubeMission;if(t&&!t.paused&&!t.ended&&!t.reload&&t.ammo<12){t.reload=1.6;tubeNotice('Reloading…');}}
