const CAMDEN_MASKED_LINES=['The woman is gone. It seems like she didn’t care about you at all.','Typical.'];
const camdenMaskedAudio=['assets/MF1.mp3','assets/MF2.mp3','assets/MF3.mp3'].map(src=>{const clip=new Audio(src);clip.preload='auto';clip.volume=.9;return clip;});
function stopCamdenMaskedVoice(){for(const clip of camdenMaskedAudio){clip.pause();clip.currentTime=0;}}
function playCamdenMaskedVoice(index){stopCamdenMaskedVoice();const clip=camdenMaskedAudio[index];if(!clip)return;clip.muted=muted;clip.play()?.catch(()=>{});}
function showCamdenTalk(){$('tubeCamdenWinnerChoice').hidden=true;$('tubeCamdenTalkNext').hidden=false;$('tubeCamdenTalkLine').textContent=CAMDEN_MASKED_LINES[tubeMission.camdenTalk];$('tubeCamdenTalkNext').textContent=tubeMission.camdenTalk===CAMDEN_MASKED_LINES.length-1?'CONTINUE':'NEXT LINE';playCamdenMaskedVoice(tubeMission.camdenTalk);}
function advanceCamdenTalk(){const t=tubeMission;if(!t||t.camdenTalk===undefined)return;if(t.camdenChoosingWinner)return;if(++t.camdenTalk<CAMDEN_MASKED_LINES.length){showCamdenTalk();return;}t.camdenChoosingWinner=true;$('tubeCamdenTalkLine').textContent='At Embankment, Richards and the woman will clash. Tell me: who should walk away alive?';$('tubeCamdenTalkNext').hidden=true;$('tubeCamdenWinnerChoice').hidden=false;playCamdenMaskedVoice(2);}
function chooseCamdenClashWinner(winner){const t=tubeMission;if(!t?.camdenChoosingWinner||!['josiah','alissa'].includes(winner))return;stopCamdenMaskedVoice();resetKevinPostTubeProgress();gameProgress.kevinTubeClashChoice=winner;delete gameProgress.kevinTubeClashWinner;t.camdenChoosingWinner=false;t.camdenExplore=false;t.ended=true;t.paused=true;t.camdenTalk=undefined;$('tubeCamdenTalk').hidden=true;gameProgress.kevinRouteStarted=true;gameProgress.tubeCompleted=true;saveProgress();refreshProgressUI();queueMicrotask(()=>{if(tubeMission===t&&mode==='tube')startKevinTubeEnding();});}

const TUBE_BETRAYAL_LINES=[
 "You really thought getting me here made us partners? Don't look so surprised.",
 "I'm an ambitious girl. I've spent too long waiting for somebody else to decide what I deserve.",
 "And you? You're small time. A way out of Brent Cross, a seat on a train. That's all you were to me.",
 "I want influence. I want people to move when I speak. I'm not throwing that away to spend my life running beside you.",
 "So this is where we part ways. Thank you for getting me to Embankment. Try not to take the rest personally."
];
function startTubeBetrayal(){const t=tubeMission;if(!t||t.cinema)return;keys.clear();mode='tubeEnding';t.paused=true;t.gun.visible=false;t.root.visible=false;document.exitPointerLock?.();$('tubeHUD').hidden=true;$('tubeOverlay').hidden=true;$('tubeSleepFade').hidden=true;t.cinema={line:0,time:0,phase:'dialogue',shot:false};const r=t.cinemaRoot=new THREE.Group();scene.add(r);const wall=mat(0x959b98),dark=mat(0x20242b);box(r,9,.2,40,dark,0,-.15,0);box(r,.25,4,40,wall,-4,1.9,0);box(r,.25,4,40,wall,4,1.9,0);box(r,8.3,.2,40,mat(0x333e42),0,3.4,0);for(let z=-16;z<=16;z+=4){box(r,5,.04,.2,new THREE.MeshBasicMaterial({color:0xe0e6df}),0,3.22,z);const light=new THREE.PointLight(0xd5dbd7,1.2,10);light.position.set(0,2.8,z);r.add(light);box(r,.06,1.6,1.6,mat(0x663044),-3.8,1.8,z);const label=tubeSign('EMBANKMENT',1.5);label.position.set(-3.73,1.8,z);label.rotation.y=Math.PI/2;r.add(label);}box(r,.12,.02,36,mat(0xc8bc83),2.7,.01,0);
 t.betrayer=makeAlissa();t.betrayer.userData.tubeTalkMouth=ball(t.betrayer.userData.head,.06,.006,.009,new THREE.MeshBasicMaterial({color:0x281016}),0,-.198,.267);t.betrayer.userData.tubeTalkMouth.visible=false;r.add(t.betrayer);t.betrayer.position.set(0,0,-2);t.betrayer.rotation.y=0;t.rescuer=makeCharacter();r.add(t.rescuer);t.rescuer.position.set(1,0,-16);t.rescuer.rotation.y=0;t.rescuer.visible=false;t.heal=new THREE.PointLight(0xffd370,0,9);r.add(t.heal);t.heal.position.set(0,1,1);t.healRing=new THREE.Mesh(new THREE.TorusGeometry(.8,.04,8,48),new THREE.MeshBasicMaterial({color:0xffd370,transparent:true,opacity:0}));r.add(t.healRing);t.healRing.position.set(0,.8,1);t.healRing.rotation.x=Math.PI/2;camera.position.set(0,1.65,1.8);camera.lookAt(0,1.65,-2);scene.fog.density=.023;scene.background.setHex(0x040509);$('tubeEndingUI').hidden=false;updateTubeBetrayalText();playTubeBetrayalVoice();}
function updateTubeBetrayalText(){const c=tubeMission.cinema;$('tubeEndingSpeaker').textContent=c.phase==='dialogue'?'ALISSA ROBERTS':c.phase==='heal'?'JOSIAH RICHARDS':'EMBANKMENT';$('tubeEndingLine').textContent=c.phase==='dialogue'?TUBE_BETRAYAL_LINES[c.line]:c.phase==='shot'?'A gunshot echoes through the empty platform.':c.phase==='leave'?'Alissa walks away, leaving you on the platform.':c.phase==='run'?'Footsteps approach. Josiah appears in the distance and runs towards you.':'Golden light closes your wounds. Josiah has healed you.';$('tubeEndingNext').hidden=c.phase!=='dialogue';}
function advanceTubeBetrayal(){const c=tubeMission?.cinema;if(mode!=='tubeEnding'||!c||c.phase!=='dialogue')return;animateTubeBetrayalMouth(tubeMission.betrayer,0,0,false);c.time=0;if(c.line<4)c.line++;else c.phase='shot';updateTubeBetrayalText();playTubeBetrayalVoice();}
function renderTubeBetrayal(dt){const t=tubeMission,c=t?.cinema;if(!c)return;c.time+=dt;const a=t.betrayer,j=t.rescuer;if(c.phase==='dialogue'){a.userData.head.rotation.y=Math.sin(c.time*1.4)*.07;animateTubeBetrayalMouth(a,c.time,dt,true);const clip=tubeBetrayalAudio[c.line];clip.muted=muted;const duration=Number.isFinite(clip.duration)?clip.duration:0;if(clip.ended||c.voiceFailed&&c.time>Math.max(6,TUBE_BETRAYAL_LINES[c.line].length*.055)||c.time>(duration||30)+10)advanceTubeBetrayal();return;}animateTubeBetrayalMouth(a,0,dt,false);
 if(c.phase==='shot'){a.userData.arms[1].rotation.x=-Math.PI/2;if(c.time>.65&&!c.shot){c.shot=true;playGunshot(.75);t.hp=12;}a.userData.muzzle.visible=c.time>.65&&c.time<.82;if(c.time>.7){camera.position.y=THREE.MathUtils.lerp(camera.position.y,.42,dt*4);camera.rotation.z=THREE.MathUtils.lerp(camera.rotation.z,.18,dt*3);}if(c.time>2){c.phase='leave';c.time=0;updateTubeBetrayalText();}}
 else if(c.phase==='leave'){a.userData.muzzle.visible=false;a.rotation.y=-Math.PI/2;a.position.x-=dt*1.5;animateCharacter(c.time,true,false,a);if(a.position.x<=-3.4)a.visible=false;if(c.time>3.5){a.visible=false;j.visible=true;c.phase='run';c.time=0;updateTubeBetrayalText();}}
 else if(c.phase==='run'){a.visible=false;j.position.z=Math.min(-.6,j.position.z+dt*4.6);animateCharacter(c.time,true,true,j);camera.lookAt(j.position.clone().add(new THREE.Vector3(0,1.5,0)));if(j.position.z>=-.6){c.phase='heal';c.time=0;t.hp=100;updateTubeBetrayalText();}}
 else if(c.phase==='heal'){a.visible=false;animateCharacter(c.time,false,false,j);j.userData.arms[0].rotation.x=-1.3;t.heal.intensity=Math.min(3,c.time*2);t.healRing.material.opacity=.6+Math.sin(c.time*5)*.25;t.healRing.scale.setScalar(1+Math.sin(c.time*2)*.15);camera.position.y=THREE.MathUtils.lerp(camera.position.y,1.65,dt*.65);camera.rotation.z=0;camera.lookAt(0,1.7,-.6);if(c.time>5)completeTubeBetrayal();}}
function completeTubeBetrayal(){stopTubeBetrayalVoice();const t=tubeMission;if(mode!=='tubeEnding'||!t)return;animateTubeBetrayalMouth(t.betrayer,0,0,false);t.hp=100;t.ended=true;t.paused=true;gameProgress.tubeCompleted=true;gameProgress.tubeBetrayalSeen=true;saveProgress();refreshProgressUI();$('tubeEndingUI').hidden=true;queueMicrotask(()=>{if(tubeMission===t&&mode==='tubeEnding')continueCompletedChapter(3);});}

function playtestTubeEnding(){if(mode!=='menu')return;$('debugResistance').checked=false;restorePlaytestSkip(3);closeChapterPicker();startTubeMission();tubeMission.elapsed=TUBE_ARRIVALS[17];updateTubeHUD();startTubeBetrayal();$('debugRestoreResult').textContent='Playtest: Tube / Embankment ending cutscene';}

// Keep the mouth fixed on the face; animate a small opening instead of stretching the lip line.
function animateTubeBetrayalMouth(actor,time,dt,speaking){const u=actor.userData,m=u.tubeTalkMouth;if(!m)return;const c=tubeMission?.cinema,clip=c?tubeBetrayalAudio[c.line]:null;let target=0;if(speaking&&clip&&!clip.paused&&!clip.ended&&!c.voiceFailed){if(tubeVoiceAnalyser){tubeVoiceAnalyser.getByteTimeDomainData(tubeVoiceSamples);let sum=0;for(const v of tubeVoiceSamples)sum+=((v-128)/128)**2;target=Math.min(.8,Math.sqrt(sum/tubeVoiceSamples.length)*8);}else target=Math.max(0,Math.sin(clip.currentTime*15))*.55;}u.tubeLipLevel=speaking?(u.tubeLipLevel||0)+(target-(u.tubeLipLevel||0))*Math.min(1,dt*22):0;m.visible=target>.018&&u.tubeLipLevel>.025;m.scale.y=.006+u.tubeLipLevel*.033;u.mouth.visible=!m.visible;u.mouth.scale.set(1,1,1);}

const tubeBetrayalAudio=["data:audio/mpeg;base64,","data:audio/mpeg;base64,","data:audio/mpeg;base64,","data:audio/mpeg;base64,","data:audio/mpeg;base64,"].map(src=>{const a=new Audio(src);a.preload='auto';return a;});
let tubeVoiceAnalyser=null,tubeVoiceSamples=null;const tubeVoiceSources=new Map();
function stopTubeBetrayalVoice(){tubeBetrayalAudio.forEach(a=>{a.pause();a.currentTime=0;});}
function playTubeBetrayalVoice(){stopTubeBetrayalVoice();const c=tubeMission?.cinema;if(!c||c.phase!=='dialogue')return;c.voiceFailed=false;initAudio();try{if(audioCtx){if(!tubeVoiceAnalyser){tubeVoiceAnalyser=audioCtx.createAnalyser();tubeVoiceAnalyser.fftSize=256;tubeVoiceSamples=new Uint8Array(256);tubeVoiceAnalyser.connect(audioCtx.destination);}for(const clip of tubeBetrayalAudio){if(!tubeVoiceSources.has(clip)){const source=audioCtx.createMediaElementSource(clip);source.connect(tubeVoiceAnalyser);tubeVoiceSources.set(clip,source);}}}}catch(e){}const clip=tubeBetrayalAudio[c.line];clip.muted=muted;clip.play()?.catch(()=>{if(tubeMission?.cinema===c)c.voiceFailed=true;});}
